SELECT 
'fdlz-datascience' as "Cluster"
,TO_DATE("start"/1000) as "startDate"
,TO_TIMESTAMP("start"/1000) as "startTimeSecond"
,DATE_TRUNC('MINUTE', CAST("start" as TIMESTAMP)) as "startTimeMinute"
,TO_DATE("start"/1000) as "finishDate"
,"finish" - "start" AS "totalDurationMS"
,1 as QueryCount
,CASE WHEN username = '$dremio$' THEN 'System' ELSE 'User' END as job_type,
CASE WHEN outcomeReason IS NULL THEN 'O|No error'
  WHEN outcomeReason IN ('-1','0','10','33','43','49','at index 0','at index 1','at index 2','at index 3','at index 4','at index 5','at index 6','at index 7','at index 9','at index 9','Index: 0, Size: 0','Index: 3, Size: 3','VARCHAR','BOOLEAN','Canceled') THEN 'D|Meaningless errors (-1, 0, 1, 10, 33, 43, 49, Canceled, VARCHAR etc.)'
  WHEN outcomeReason = 'ConnectException: Connection refused' THEN '?|ConnectException: Connection refused'
  WHEN outcomeReason = 'NullPointerException' then 'D|NPE: Just NullPointerException'
  WHEN outcomeReason = 'Statement preparation aborted' then '?|Statement preparation aborted'
  WHEN outcomeReason = 'Unable to start resources within requested time.' then '?|Unable to start resources within requested time.'
  WHEN outcomeReason = 'Reflection has been updated since reflection was scheduled.' then 'U|Reflection has been updated since reflection was scheduled.'
  WHEN outcomeReason = 'Failure parsing the query.' then 'U|Failure parsing the query.'
  WHEN outcomeReason = 'ORDER BY expression should not contain OVER clause' then 'U|ORDER BY expression should not contain OVER clause'
  WHEN outcomeReason = 'Flatten does not support empty list.' then 'U|Flatten does not support empty list.'
  WHEN outcomeReason = 'Failed to get rel from the request' then '?|Failed to get rel from the request'
  WHEN outcomeReason = 'There is no row access policy to drop' then 'U|There is no row access policy to drop'
  WHEN (POSITION('Object ''' in outcomeReason) = 1 AND POSITION(''' not found' in outcomeReason) = (LENGTH(outcomeReason) - LENGTH(''' not found') + 1))
    OR (POSITION('SqlValidatorException: Object ''' in outcomeReason) = 1 AND POSITION(''' not found' in outcomeReason) = (LENGTH(outcomeReason) - LENGTH(''' not found') + 1))
    OR (POSITION('Object ''' in outcomeReason) = 1 AND POSITION(' not found within'  in outcomeReason) > 0) then 'U|Object O not found'
  WHEN (POSITION('Table ''' in outcomeReason) = 1 AND POSITION(''' not found' in outcomeReason) = (LENGTH(outcomeReason) - LENGTH(''' not found') + 1)) then 'U|Table T not found'
  WHEN POSITION('Failed to drop table: ' in outcomeReason) = 1 then 'U|Failed to drop table (MultiObjectDeleteException?)' 
  WHEN POSITION('Folder ' in outcomeReason) = 1 AND POSITION(' already exists' in outcomeReason) > 0 then 'U|Folder F already exists' 
  WHEN POSITION('(io.grpc.StatusRuntimeException) UNKNOWN' in outcomeReason) > 0 AND POSITION('com.dremio.service.catalog.DatasetCatalogServiceGrpc$DatasetCatalogServiceBlockingStub.getDataset()' in outcomeReason) > 0 then 'D|DatasetCatalogServiceBlockingStub.getDataset() ServiceRuntimeException' 
  WHEN POSITION('Partition ''' in outcomeReason) > 0 AND POSITION(''' does not exist in ' in outcomeReason) > 0 then 'U|Partition P does not exist' 
  WHEN POSITION('The file /samples.dremio.com' in outcomeReason) > 0 AND POSITION('is not in Parquet format' in outcomeReason) > 0 then 'U|SPECIAL: Old Parquet samples need to be repromoted as Iceberg tables (not in Parquet format)' 
  WHEN POSITION('FileNotFoundException: File dremioAzureStorage://:/uscdotpdprojectstore/metadata/' in outcomeReason) > 0 OR POSITION('FileNotFoundException: File dremioAzureStorage://:/dremiocloudafcustdev/metadata/' in outcomeReason) > 0 then 'U|SPECIAL: PWC metadata issues' 
  WHEN POSITION('metadata.json does not exist in the following directory: /uscdotpdprojectstore/metadata/' in outcomeReason) > 0 then 'U|SPECIAL: PWC empty project store (FileNotFoundException)' 
  WHEN POSITION('hello_world.txt is not in Parquet format' in outcomeReason) > 0 then 'U|SPECIAL: Moderna''s invalid table format (hello_world.txt is not in Parquet format)'
  WHEN POSITION('Dremio does not support casting or coercing' in outcomeReason) > 0 THEN 'U|Dremio does not support casting or coercing'
  WHEN POSITION('Please check the size and format of the files you are promoting and select the format from the dropdown box accordingly' in outcomeReason) > 0 THEN 'U|The file <file> is not in Parquet format'
  WHEN POSITION('Reflection could not be created as it uses context-sensitive functions. Functions like IS_MEMBER, USER, etc. cannot be used in reflections since they require context to complete.' in outcomeReason) > 0 THEN 'U|Reflection could not be created as it uses context-sensitive functions'
  WHEN POSITION('Query canceled - out of memory, check the query profile for details' in outcomeReason) > 0 THEN '?|Query cancelled by coordinator heap monitor (memory)'
  WHEN POSITION('Query canceled by executor heap monitor' in outcomeReason) > 0 THEN '?|Query cancelled by executor heap monitor (memory)'
  WHEN POSITION('Heap monitor detected that the heap is almost full' in outcomeReason) > 0 THEN '?|Query cancelled by executor heap monitor (memory)'
  WHEN POSITION('MemoryArbiter detected no memory available' in outcomeReason) > 0 THEN '?|MemoryArbiter detected no memory available (memory)'
  WHEN POSITION('Query canceled by MemoryArbiter' in outcomeReason) > 0 THEN '?|Query cancelled by MemoryArbiter (memory)'
  WHEN POSITION('(io.netty.util.internal.OutOfDirectMemoryError) failed to allocate' in outcomeReason) > 0 THEN '?|OutOfDirectMemoryError: failed to allocate x byte(s) of direct memory (memory)'
  WHEN POSITION('Query cancelled by user' in outcomeReason) > 0 THEN 'U|Query cancelled by user'
  WHEN POSITION('host=wizard-prod-replica-2.cn3ixam1w40x.eu-west-2.rds.amazonaws.com' in outcomeReason) > 0 THEN 'U|Merlin: Failure getting source [MySQL Prod]'
  WHEN POSITION('] uses an unsupported file format' in outcomeReason) > 0 THEN 'U|AWS Glue table [<table>] uses an unsupported file format'
  WHEN POSITION('Failed to spill to disk. Please check space availability' in outcomeReason) > 0 THEN 'U|Failed to spill to disk. Please check space availability'
  WHEN POSITION('Function ''{fn locate}'' is not defined' in outcomeReason) > 0 THEN 'U|Function ''{fn locate}'' is not defined'
  WHEN POSITION('Illegal use of ''NULL''' in outcomeReason) > 0 THEN 'U|Illegal use of ''NULL'''
  WHEN POSITION('Incremental refresh did not find previous DONE materialization' in outcomeReason) > 0 THEN 'U|Incremental refresh did not find previous DONE materialization'
  WHEN POSITION('Job was cancelled because the query went beyond system capacity during query planning.' in outcomeReason) > 0 THEN 'L|Job was cancelled because the query went beyond system capacity during query planning.'
  WHEN POSITION('No executors are available for data with hard affinity. You may consider using "registration.publish-host" property if your network rules change.' in outcomeReason) > 0 THEN '?|No executors are available for data with hard affinity. You may consider using "registration.publish-host" property if your network rules change.'
  WHEN POSITION('No matching reflection found.' in outcomeReason) > 0 THEN 'U|No matching reflection found.'
  WHEN POSITION('Not authorized to use external query.' in outcomeReason) > 0 THEN 'U|Not authorized to use external query.'
  WHEN POSITION('query cost too hgih >=' in outcomeReason) > 0 THEN 'U|query cost too hgih >='
  WHEN POSITION('Query was rejected based on a rule that did not specify a rejection reason.' in outcomeReason) > 0 THEN 'U|Query was rejected based on a rule that did not specify a rejection reason'
  WHEN POSITION('RpcException: Timeout while waiting for client to be in ready state.' in outcomeReason) > 0 THEN '?|RpcException: Timeout while waiting for client to be in ready state'
  WHEN POSITION('Selective refresh is not allowed on unknown datasets. Please run full refresh on' in outcomeReason) > 0 THEN 'U|Selective refresh is not allowed on unknown datasets. Please run full refresh on <dataset>'
  WHEN POSITION('System user is not allowed to execute queries via UI. Please use your own user account instead.' in outcomeReason) > 0 THEN 'U|System user is not allowed to execute queries via UI'
  WHEN POSITION('Unable to find any files for datasets.' in outcomeReason) > 0 THEN 'U|Unable to find any files for datasets'
  WHEN POSITION('Unable to get Hive table InputFormat class. There is neither InputFormat class explicitly specified nor a StorageHandler class provided.' in outcomeReason) > 0 THEN 'U|Unable to get Hive table InputFormat class'
  WHEN POSITION('Access denied. You do not have USAGE privilege on the engine.' in outcomeReason) > 0 THEN 'U|Access denied. You do not have USAGE privilege on the engine.'
  WHEN POSITION('Access denied. You do not have USAGE privilege on the project.' in outcomeReason) > 0 THEN 'U|Access denied. You do not have USAGE privilege on the project.'
  WHEN POSITION('Failure finding function:' in outcomeReason) > 0 THEN 'U|Failure finding function: <function signature>'
  WHEN POSITION('java.net.UnknownHostException' in outcomeReason) > 0 THEN 'U|UnknownHostException'
  WHEN POSITION('Caused By (java.net.UnknownHostException)' in outcomeReason) > 0 THEN 'U|UnknownHostException'
  WHEN POSITION('A table with the given name already exists' in outcomeReason) > 0 THEN 'U|Already exists'
  WHEN POSITION('already exists in schema' in outcomeReason) > 0 THEN 'U|Already exists'
  WHEN POSITION('Access denied reading dataset' in outcomeReason) > 0 THEN 'U|Access denied reading dataset'
  WHEN POSITION('AccessControlException:' in outcomeReason) > 0 THEN 'U|AccessControlException'
  WHEN POSITION('AccessControlException:' in outcomeReason) > 0 THEN 'U|AccessControlException'
  WHEN POSITION('Aggregate expression is illegal in GROUP BY clause' in outcomeReason) > 0 THEN 'U|Aggregate expression error'
  WHEN POSITION('Aggregate expression is illegal in WHERE clause' in outcomeReason) > 0 THEN 'U|Aggregate expression error'
  WHEN POSITION('Aggregate expression is illegal in ORDER BY clause of non-aggregating SELECT' in outcomeReason) > 0 THEN 'U|Aggregate expression error'
  WHEN POSITION('Aggregate expressions cannot be nested' in outcomeReason) > 0 THEN 'U|Aggregate expression error'
  WHEN POSITION('All arguments of call to macro' in outcomeReason) > 0 THEN 'U|All arguments of call to macro should be literal'
  WHEN POSITION('AmazonS3Exception: Access Denied (Service: Amazon S3; Status Code: 403;' in outcomeReason) > 0 THEN 'U|AmazonS3Exception: Access Denied (Service: Amazon S3; Status Code: 403;'
  WHEN POSITION('(com.amazonaws.services.s3.model.AmazonS3Exception) Access Denied (Service: Amazon S3; Status Code: 403;' in outcomeReason) > 0 THEN 'U|AmazonS3Exception: Access Denied (Service: Amazon S3; Status Code: 403;'
  WHEN POSITION('Access denied on s3://' in outcomeReason) > 0 THEN 'U|Access denied on s3://<path>'
  WHEN POSITION('because no identity-based policy allows the kms:GenerateDataKey action' in outcomeReason) > 0 THEN 'U|User is not authorized to perform kms:GenerateDataKey on resource'
  WHEN POSITION('AmazonS3Exception: The specified bucket does not exist' in outcomeReason) > 0 THEN 'U|AmazonS3Exception: The specified bucket does not exist'
  WHEN POSITION('AmazonS3Exception: Forbidden (' in outcomeReason) > 0 THEN 'U|AmazonS3Exception: Forbidden (403)'
  WHEN POSITION('AmazonS3Exception) The ciphertext refers to a customer master key' in outcomeReason) > 0 THEN 'U|AmazonS3Exception: The ciphertext refers to a customer master key that does not exist'
  WHEN POSITION('is not authorized to perform' in outcomeReason) > 0 THEN 'U|AmazonS3Exception: User is not authorized to perform <action> on resource'
  WHEN POSITION('Argument to function ''' in outcomeReason) > 0 THEN 'U|Argument to function must be a literal'
  WHEN POSITION('ARRAY_AGG currently does not support ordering within group' in outcomeReason) > 0 THEN 'U|ARRAY_AGG does not support ...'
  WHEN POSITION('ARRAY_AGG is not supported for NULL' in outcomeReason) > 0 THEN 'U|ARRAY_AGG does not support ...'
  WHEN POSITION('Invalid number of arguments to function' in outcomeReason) > 0 THEN 'U|Invalid number of arguments to function'
  WHEN POSITION('columns including leaf level fields of complex type are allowed to be scanned' in outcomeReason) > 0 THEN 'L|At most N columns including leaf level fields of complex type are allowed to be scanned'
  WHEN POSITION(' no longer active. Cancelling fragment ' in outcomeReason) > 0 THEN '?|AttemptManager <host> no longer active. Cancelling fragment <f>'
  WHEN POSITION('BETWEEN operator has no terminating AND' in outcomeReason) > 0 THEN 'U|BETWEEN operator has no terminating AND'
  WHEN POSITION('CONVERT_FROM does not support conversion from type' in outcomeReason) > 0 THEN 'U|CONVERT_FROM does not support conversion from type T'
  WHEN POSITION('Cannot apply = to the two different charsets' in outcomeReason) > 0 THEN 'U|Cannot apply = to the two different charsets C1 and C2'
  WHEN POSITION('Supported form(s)' in outcomeReason) > 0 THEN 'U|Cannot apply X to arguments of type'
  WHEN POSITION('since it has child tables' in outcomeReason) > 0 THEN 'L|Cannot drop table T since it has child tables'
  WHEN POSITION('Cannot create view in' in outcomeReason) > 0 THEN '?|Cannot create view in X'
  WHEN POSITION('does not support create view' in outcomeReason) > 0 THEN 'U|Source does not support view operations'
  WHEN POSITION('does not support update view' in outcomeReason) > 0 THEN 'U|Source does not support view operations'
  WHEN POSITION('does not support view operations' in outcomeReason) > 0 THEN 'U|Source does not support view operations'
  WHEN POSITION('Cannot assign to target field' in outcomeReason) > 0 THEN '?|Cannot assign to target field F1 of type T1 from source field F2 of type T2'
  WHEN POSITION('Cannot convert RexNode to equivalent Dremio expression' in outcomeReason) > 0 THEN '?|Cannot convert RexNode to equivalent Dremio expression'
  WHEN POSITION('while it is set in the current session''s reference context' in outcomeReason) > 0 THEN 'U|Cannot drop branch/tag X for source S while it is set in the current session''s reference context'
  WHEN POSITION('Cannot find table to create view from' in outcomeReason) > 0 THEN 'U|Cannot find table to create view from'
  WHEN POSITION('does not accept the supplied operand types: ' in outcomeReason) > 0 THEN 'U|FUNCTION does not accept the supplied operand types'
  WHEN POSITION('Cast function cannot convert value of type' in outcomeReason) > 0 THEN 'U|Cast function cannot convert value of type T1 to type T2'
  WHEN POSITION('Cannot infer type of field' in outcomeReason) > 0 THEN '?|Cannot infer type of field F within ROW type'
  WHEN POSITION('Cannot change data type of column' in outcomeReason) > 0 THEN 'U|Cannot change data type of column C from T1 to T2'
  WHEN POSITION('Cannot specify condition (NATURAL keyword, or ON or USING clause) following CROSS JOIN' in outcomeReason) > 0 THEN 'U|Cannot specify condition (NATURAL keyword, or ON or USING clause) following CROSS JOIN'
  WHEN POSITION('cannot translate call' in outcomeReason) > 0 THEN 'D|cannot translate call'
  WHEN POSITION('Change in Hive partition definition detected for table' in outcomeReason) > 0 THEN '?|Change in Hive partition definition detected for table T, re-promote the table to update the partition definition.'
  WHEN POSITION('Changing advanced system settings is not supported on Dremio Cloud.' in outcomeReason) > 0 THEN 'U|Changing advanced system settings is not supported on Dremio Cloud.'
  WHEN POSITION('ChannelClosedException: [USER]: Channel closed' in outcomeReason) > 0 THEN '?|ChannelClosedException: [USER]'
  WHEN POSITION('ChannelClosedException: [FABRIC]: Channel closed null <--> null (fabric client)' in outcomeReason) > 0 THEN '?|ChannelClosedException: [FABRIC]'
  WHEN POSITION('ChannelClosedException: [FABRIC]: Channel closed' in outcomeReason) > 0 THEN '?|ChannelClosedException'
  WHEN POSITION(''' not found in any table' in outcomeReason) > 0 THEN 'U|Column C not found in [any] table'
  WHEN POSITION(''' not found in table ''' in outcomeReason) > 0 THEN 'U|Column C not found in [any] table'
  WHEN POSITION('Column count mismatch in ' in outcomeReason) > 0 THEN 'U|Column count mismatch in UNION [ALL] | EXCEPT'
  WHEN POSITION(''' is ambiguous' in outcomeReason) > 0 THEN 'U|Column C is ambiguous'
  WHEN POSITION('] already in the table.' in outcomeReason) > 0 THEN 'U|Column C already in the table.'
  WHEN POSITION('is not present in table' in outcomeReason) > 0 THEN 'U|Column C is not present in table T'
  WHEN POSITION('Column has duplicate column name' in outcomeReason) > 0 THEN 'U|Duplicate column/relation name'
  WHEN POSITION('clause is not unique on one side of join' in outcomeReason) > 0 THEN 'U|Column name ... is not unique on one side of join'
  WHEN POSITION('specified multiple times.' in outcomeReason) > 0 THEN 'U|Column [<column>] specified multiple times'
  WHEN POSITION('Columns/Fields not specified for table.' in outcomeReason) > 0 THEN 'U|Columns/Fields not specified for table'
  WHEN POSITION(': error: too many constants' in outcomeReason) > 0 THEN 'D|CompileException: too many constants'
  WHEN POSITION(': error: code too large' in outcomeReason) > 0 THEN 'D|CompileException: code too large'
  WHEN POSITION('CommitFailedException) Version ' in outcomeReason) > 0 THEN '?|CommitFailedException: Version X already exists: <file>'
  WHEN POSITION('CommitFailedException: Table metadata refresh is required' in outcomeReason) > 0 THEN '?|CommitFailedException: Table metadata refresh is required'
  WHEN POSITION('CompileException) Compilation failed' in outcomeReason) > 0 THEN 'D|CompileException: Compilation failed'
  WHEN POSITION('Commit log is empty' in outcomeReason) > 0 THEN '?|Commit log is empty'
  WHEN POSITION('CompileException: Line' in outcomeReason) > 0 THEN '?|CompileException: Line X, Column Y'
  WHEN POSITION('ConcurrentModificationException: Document with' in outcomeReason) > 0 THEN '?|CME: Document with _id <id> (version <v>) already modified. You cannot save it now.'
  WHEN POSITION('ConcurrentModificationException: tried to update version' in outcomeReason) > 0 THEN '?|CME: tried to update version v1, found previous version v2'
  WHEN POSITION('ABORTED: Tag mismatch when updating dataset.' in outcomeReason) > 0 THEN '?|CME: Tag mismatch when updating dataset'
  WHEN POSITION('Concurrent DML operation has updated the table, please retry.' in outcomeReason) > 0 THEN 'U|CME: Concurrent DML operation has updated the table'
  WHEN POSITION('ABORTED: Tried to update a dataset that does not exist' in outcomeReason) > 0 THEN '?|CME: Tried to update a dataset that does not exist'
  WHEN POSITION('was updated, and the given configuration has older ctime' in outcomeReason) > 0 THEN '?|CME: Source [<source>] was updated, and the given configuration has older ctime'
  WHEN POSITION('Unable to refresh metadata for the dataset (due to concurrent updates). Please retry.' in outcomeReason) > 0 THEN 'U|CME: Unable to refresh metadata for the dataset (due to concurrent updates). Please retry.'
  WHEN POSITION('Unable to get task leader while trying to get ' in outcomeReason) > 0 THEN '?|Unable to get task leader while trying to get function/statistics/reflection information'
  WHEN POSITION('CONNECTION ERROR: Connection null <--> null (user client) closed unexpectedly. SabotNode down?' in outcomeReason) > 0 THEN '?|CONNECTION ERROR: Connection null <--> null (user client) closed unexpectedly. SabotNode down?'
  WHEN POSITION('ConnectException: Connection refused (Connection refused)' in outcomeReason) > 0 THEN '?|ConnectException: Connection refused'
  WHEN POSITION('ConnectException: finishConnect(..) failed: Connection refused' in outcomeReason) > 0 THEN '?|ConnectException: Connection refused'
  WHEN POSITION('A constant expression was encountered in the ORDER BY list' in outcomeReason) > 0 THEN 'U|A constant expression was encountered in the ORDER BY list'
  WHEN POSITION('Caused By (java.net.ConnectException) Connection refused' in outcomeReason) > 0 THEN '?|ConnectException: Connection refused'
  WHEN POSITION('Could not load value for key s3' in outcomeReason) > 0 THEN '?|Could not load value for key s3://<path>'
  WHEN POSITION('Could not send message to executor node for tag' in outcomeReason) > 0 THEN '?|Could not send message to executor node for tag T'
  WHEN POSITION('Create User failed: Setting password here is not allowed. Please set the password via the invite link in the email.' in outcomeReason) > 0 THEN 'U|Create User failed: Setting password here is not allowed'
  WHEN POSITION('Creating buckets is not supported' in outcomeReason) > 0 THEN 'U|Creating buckets is not supported'
  WHEN POSITION('Currently Very large case statements cannot have Gandiva only functions' in outcomeReason) > 0 THEN 'D|Currently Very large case statements cannot have Gandiva only functions'
  WHEN POSITION('(com.dremio.datastore.DatastoreException) Failed to get from store id' in outcomeReason) > 0 THEN '?|DatastoreException: Failed to get from store id'
  WHEN POSITION('does not exist or is not a table' in outcomeReason) > 0 THEN 'U|Dataset D does not exist or is not a table'
  WHEN POSITION('CTAS query cancelled because it will generate more than the limit of' in outcomeReason) > 0 THEN 'L|CTAS query cancelled because it will generate more than the limit of N partitions'
  WHEN POSITION('This version of the table ' in outcomeReason) > 0 THEN 'U|This version of the table [<table> is not available'
  WHEN POSITION('DATA_READ ERROR: With retry attempt failed to list files of directory' in outcomeReason) > 0 THEN '?|DATA_READ ERROR: With retry attempt failed to list files of directory D'
  WHEN POSITION('(java.lang.IllegalStateException) All the directories should have = in the partition structure' in outcomeReason) > 0 THEN 'U|All the directories should have = in the partition structure (IllegalStateException)'
  WHEN POSITION(') Error while streaming resultSet data
    org.mariadb.jdbc.export.ExceptionFactory.createException()' in outcomeReason) > 0 THEN '?|java.sql.SQLNonTransientConnectionException: Error while streaming resultSet data (mariadb)'
  WHEN POSITION(') Query execution was interrupted
    org.mariadb.jdbc.export.ExceptionFactory.createException()' in outcomeReason) > 0 THEN '?|java.sql.SQLTimeoutException: Query execution was interrupted (mariadb)'
  WHEN POSITION('(com.amazon.redshift.util.RedshiftException) ERROR: could not open relation with' in outcomeReason) > 0 THEN '?|RedshiftException: could not open relation with OID'
  WHEN POSITION('(org.postgresql.util.PSQLException) ERROR: canceling statement due to user request' in outcomeReason) > 0 THEN '?|PSQLException: canceling statement due to user request'
  WHEN POSITION('(net.snowflake.client.jdbc.SnowflakeSQLLoggedException) JDBC driver internal error' in outcomeReason) > 0 THEN '?|SnowflakeSQLLoggedException: JDBC driver internal error'
  WHEN POSITION('(java.sql.SQLException) ORA-02391: exceeded simultaneous SESSIONS_PER_USER limit' in outcomeReason) > 0 THEN '?|ORA-02391: exceeded simultaneous SESSIONS_PER_USER limit'
  WHEN POSITION('(org.postgresql.util.PSQLException) An I/O error occurred while sending to the backend' in outcomeReason) > 0 THEN '?|PSQLException: An I/O error occurred while sending to the backend'
  WHEN POSITION('communication buffer resources with another process and has been chosen as the deadlock victim' in outcomeReason) > 0 THEN '?|SQLServerException: Transaction (Process ID X) was deadlocked on lock | communication buffer resources with another process and has been chosen as the deadlock victim'
  WHEN POSITION(' is not supported on this' in outcomeReason) > 0 THEN 'U|<COMMAND> is not supported on this VIEW/SYSTEM_TABLE'
  WHEN POSITION('DISTINCT for window aggregate functions is not currently supported' in outcomeReason) > 0 THEN 'U|DISTINCT for window aggregate functions is not currently supported'
  WHEN POSITION('DatasetNotFoundException: Missing version' in outcomeReason) > 0 THEN '?|DatasetNotFoundException'
  WHEN POSITION('DatasetVersionNotFoundException: dataset' in outcomeReason) > 0 THEN '?|DatasetVersionNotFoundException'
  WHEN POSITION('Dremio does not currently support order by with ordinals in over clause' in outcomeReason) > 0 THEN 'U|Dremio does not currently support order by with ordinals in over clause'
  WHEN POSITION('Dremio doesn''t support using FLATTEN within DISTINCT' in outcomeReason) > 0 THEN 'U|Dremio doesn''t support using FLATTEN within DISTINCT'
  WHEN POSITION('Dremio only supports single statement execution' in outcomeReason) > 0 THEN 'U|Dremio only supports single statement execution. Unable to execute the given query with N statements'
  WHEN POSITION('Duplicate column name' in outcomeReason) > 0 THEN 'U|Duplicate column/relation name'
  WHEN POSITION('Duplicate relation name' in outcomeReason) > 0 THEN 'U|Duplicate column/relation name'
  WHEN POSITION('EOFException) Reached the end of stream with' in outcomeReason) > 0 THEN '?|EOFException: Reached the end of stream with X bytes left to read'
  WHEN POSITION('Error during planning the query.' in outcomeReason) > 0 THEN '?|Error during planning the query'
  WHEN POSITION('Error setting up remote fragment execution' in outcomeReason) > 0 THEN 'D|Error setting up remote fragment execution'
  WHEN POSITION('Caused By (java.lang.IllegalStateException) Received data batch for' in outcomeReason) > 0 THEN 'D|IllegalStateException: Received data batch for X from Y before fragment executor started'
  WHEN POSITION('Error while applying rule' in outcomeReason) > 0 THEN '?|Error while applying rule'
  WHEN POSITION('while waiting after sending work fragments to remote nodes. Sent' in outcomeReason) > 0 THEN '?|Exceeded timeout (N) while waiting after sending work fragments to remote nodes'
  WHEN POSITION('One or more result batches failed with ack timeout' in outcomeReason) > 0 THEN '?|One or more result batches failed with ack timeout'
  WHEN POSITION('Timed out while waiting for job results request response' in outcomeReason) > 0 THEN '?|Timed out while waiting for job results request response'
  WHEN POSITION('ExecutionSetupException: One or more nodes lost connectivity during query.' in outcomeReason) > 0 THEN '?|One or more nodes lost connectivity during query (ExecutionSetupException)'
  WHEN POSITION('Expected a boolean type' in outcomeReason) > 0 THEN 'U|Expected a boolean type'
  WHEN POSITION('Expected query or join' in outcomeReason) > 0 THEN 'U|Expected query or join'
  WHEN POSITION(''' is not being grouped' in outcomeReason) > 0 THEN 'U|Expression E is not being grouped'
  WHEN POSITION('FORGET METADATA is not supported on tables in homespace, sys, or INFORMATION_SCHEMA.' in outcomeReason) > 0 THEN 'U|FORGET METADATA is not supported on tables in homespace, sys, or INFORMATION_SCHEMA.'
  WHEN POSITION(''' is not in the select clause' in outcomeReason) > 0 THEN 'U|Expression E is not in the select clause'
  WHEN POSITION('Failed to build reflections on top of view/table with access controls' in outcomeReason) > 0 THEN 'U|Failed to build reflections on top of view/table with access controls'
  WHEN POSITION('Failed to check run query access privileges' in outcomeReason) > 0 THEN '?|Failed to check run query access privileges'
  WHEN POSITION('Failed to create new input stream for file:' in outcomeReason) > 0 THEN '?|Failed to create new input stream for file'
  WHEN POSITION('ERROR Failure to create directory' in outcomeReason) > 0 THEN '?|Failure to create directory'
  WHEN POSITION('MultiObjectDeleteException: One or more objects could not be deleted' in outcomeReason) > 0 THEN 'U|MultiObjectDeleteException: One or more objects could not be deleted'
  WHEN POSITION('Failed to find row access policy,' in outcomeReason) > 0 THEN 'U|Failed to find row access policy'
  WHEN POSITION('Failed to get iceberg metadata:' in outcomeReason) > 0 THEN '?|Failed to get iceberg metadata'
  WHEN POSITION('Failed to load the Iceberg table. Please make sure to use correct Iceberg catalog' in outcomeReason) > 0 THEN '?|Failed to load the Iceberg table'
  WHEN POSITION('Failed to load the Iceberg table. The underlying metadata and/or data files may not exist' in outcomeReason) > 0 THEN '?|Failed to load the Iceberg table'
  WHEN POSITION('org.apache.hadoop.hdfs.server.namenode.SafeModeException' in outcomeReason) > 0 THEN 'U|org.apache.hadoop.hdfs.server.namenode.SafeModeException: Name node is in safe mode.'
  WHEN POSITION('Failed to open input stream for file:' in outcomeReason) > 0 THEN '?|Failed to open stream for file'
  WHEN POSITION('Failed to open a new stream for file :' in outcomeReason) > 0 THEN '?|Failed to open stream for file'
  WHEN POSITION('Failed to read metadata for delta dataset' in outcomeReason) > 0 THEN '?|Failed to read metadata for delta dataset <path>'
  WHEN POSITION('Failure creating parser for entry' in outcomeReason) > 0 THEN '?|Failure creating parser for entry'
