  WHEN POSITION('(java.lang.NullPointerException) null' in outcomeReason) > 0 THEN '?|NPE'
  WHEN POSITION('NullPointerException' in outcomeReason) > 0 THEN '?|NPE'
  WHEN POSITION(''' not found' in outcomeReason) > 0 THEN '?|Object not found (very generic)'
  WHEN POSITION('" not found' in outcomeReason) > 0 THEN '?|Object not found (very generic)'
  WHEN POSITION('Ordinal out of range' in outcomeReason) > 0 THEN '?|Ordinal out of range'
  WHEN POSITION(''' returned error ''' in outcomeReason) > 0 THEN '?|Source ''<source>'' returned error ''<error>'''
  WHEN POSITION('Source branch' in outcomeReason) > 0 THEN '?|Source branch S1 not found in Source S2'
  WHEN POSITION('StackOverflowError' in outcomeReason) > 0 THEN '?|StackOverflowError'
  WHEN POSITION('StatusRuntimeException: UNKNOWN' in outcomeReason) > 0 THEN '?|StatusRuntimeException: UNKNOWN'
  WHEN POSITION('(io.grpc.StatusRuntimeException) UNKNOWN' in outcomeReason) > 0 THEN '?|StatusRuntimeException: UNKNOWN'
  WHEN POSITION('StatusRuntimeException' in outcomeReason) > 0 THEN '?|StatusRuntimeException'
  WHEN POSITION('] not found' in outcomeReason) > 0 THEN 'U|Table T not found'
  WHEN POSITION('] does not exist.' in outcomeReason) > 0 THEN '?|Table T does not exist'
  WHEN POSITION('] is currently unavailable. Info' in outcomeReason) > 0 THEN '?|The source S is currently unavailable. Metadata is not accessible.'
  WHEN POSITION('] is currently unavailable. Metadata' in outcomeReason) > 0 THEN '?|The source S is currently unavailable. Metadata is not accessible.'
  WHEN POSITION('TimeoutException' in outcomeReason) > 0 THEN '?|TimeoutException'
  WHEN POSITION('Unknown field ''' in outcomeReason) > 0 THEN '?|Unknown field F'
  WHEN POSITION('UnsupportedOperationException' in outcomeReason) > 0 THEN '?|UnsupportedOperationException'
  WHEN POSITION('ExecutionSetupException' in outcomeReason) > 0 THEN '?|ExecutionSetupException'
  WHEN POSITION('com.dremio.connector.ConnectorException' in outcomeReason) > 0 THEN '?|ConnectorException'
  WHEN POSITION('(org.apache.hadoop.fs.s3a.AWSClientIOException) getFileStatus on' in outcomeReason) > 0 THEN '?|Error during getFileStatus'
  WHEN POSITION('Error while getting dataset config' in outcomeReason) > 0 THEN '?|Error while getting dataset config'
  WHEN POSITION('while converting ' in outcomeReason) > 0 THEN '?|while converting ...'
  WHEN POSITION('OutOfMemoryError' in outcomeReason) > 0 THEN '?|OutOfMemoryError'
  WHEN POSITION('OutOfMemoryException' in outcomeReason) > 0 THEN '?|OutOfMemoryException'
  WHEN POSITION('Failure getting source [' in outcomeReason) > 0 THEN '?|Failure getting source [S]'
ELSE '?|Something else'
END as "category|error"
,*
FROM "aws-s3"."kamlesh-rsa"."wells-fargo"."queries-json"."fdlz-datascience"
where queueName != ''